# filename: sanity_check.py

data = {
    "Oko, Thief of Crowns": {"high": 42.25, "low": 12.10},
    "Once Upon a Time": {"high": 38.00, "low": 1.55},
    "Veil of Summer": {"high": 15.25, "low": 4.10}
}

def basic_sanity(d):
    for k, v in d.items():
        if not isinstance(v["high"], (int, float)) or not isinstance(v["low"], (int, float)):
            return False, f"{k} has non-numeric values"
        if v["high"] <= 0 or v["low"] < 0:
            return False, f"{k} has invalid sign values"
        if v["high"] <= v["low"]:
            return False, f"{k} violates high > low"
    return True, "All entries valid and consistent"

ok, msg = basic_sanity(data)
print(msg)

# compute drops and ranking
drops = {k: round(v["high"] - v["low"], 2) for k, v in data.items()}
sorted_names = sorted(drops, key=drops.get, reverse=True)
print("Computed drops:", drops)
print("Ranking:", sorted_names)
